create or replace function public.create_or_update_profile(username text)
returns jsonb
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_user_id uuid;
  v_username text;
  v_email text;
  v_profile public.profiles%rowtype;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    return jsonb_build_object(
      'success', false,
      'error_code', 'NOT_AUTHENTICATED',
      'message', 'Utilisateur non connecté.'
    );
  end if;

  v_username := nullif(btrim($1), '');

  if v_username is null then
    return jsonb_build_object(
      'success', false,
      'error_code', 'USERNAME_REQUIRED',
      'message', 'Le pseudo est obligatoire.'
    );
  end if;

  v_email := auth.jwt() ->> 'email';

  insert into public.profiles (id, email, username)
  values (v_user_id, v_email, v_username)
  on conflict (id) do update
    set email = coalesce(excluded.email, public.profiles.email),
        username = excluded.username
  returning *
  into v_profile;

  return jsonb_build_object(
    'success', true,
    'data', jsonb_build_object(
      'id', v_profile.id,
      'email', v_profile.email,
      'username', v_profile.username,
      'avatar_url', v_profile.avatar_url,
      'created_at', v_profile.created_at
    )
  );
end;
$$

create or replace function public.create_company(name text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid;
  v_name text;
  v_prefix text;
  v_invite_code text;
  v_company public.companies%rowtype;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    return jsonb_build_object(
      'success', false,
      'error_code', 'NOT_AUTHENTICATED',
      'message', 'Utilisateur non connecté.'
    );
  end if;

  v_name := nullif(btrim($1), '');

  if v_name is null then
    return jsonb_build_object(
      'success', false,
      'error_code', 'COMPANY_NAME_REQUIRED',
      'message', 'Le nom de l’entreprise est obligatoire.'
    );
  end if;

  v_prefix := upper(regexp_replace(v_name, '[^a-zA-Z0-9]+', '', 'g'));
  v_prefix := left(coalesce(nullif(v_prefix, ''), 'COMP') || 'COMP', 4);

  loop
    v_invite_code := v_prefix || '-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 5));

    exit when not exists (
      select 1
      from public.companies
      where companies.invite_code = v_invite_code
    );
  end loop;

  insert into public.companies (name, invite_code, created_by)
  values (v_name, v_invite_code, v_user_id)
  returning *
  into v_company;

  insert into public.company_members (user_id, company_id, role)
  values (v_user_id, v_company.id, 'member')
  on conflict (user_id, company_id) do nothing;

  return jsonb_build_object(
    'success', true,
    'data', jsonb_build_object(
      'company_id', v_company.id,
      'name', v_company.name,
      'invite_code', v_company.invite_code,
      'invite_url_path', '/join/' || v_company.invite_code
    )
  );
end;
$$

create or replace function public.join_company_by_invite_code(invite_code text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid;
  v_invite_code text;
  v_company public.companies%rowtype;
  v_inserted_membership_id uuid;
  v_membership_status text;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    return jsonb_build_object(
      'success', false,
      'error_code', 'NOT_AUTHENTICATED',
      'message', 'Utilisateur non connecté.'
    );
  end if;

  v_invite_code := upper(nullif(btrim($1), ''));

  select *
  into v_company
  from public.companies
  where companies.invite_code = v_invite_code;

  if v_company.id is null then
    return jsonb_build_object(
      'success', false,
      'error_code', 'INVALID_INVITE_CODE',
      'message', 'Ce lien d’invitation est invalide.'
    );
  end if;

  insert into public.company_members (user_id, company_id, role)
  values (v_user_id, v_company.id, 'member')
  on conflict (user_id, company_id) do nothing
  returning id
  into v_inserted_membership_id;

  if v_inserted_membership_id is null then
    v_membership_status := 'already_member';
  else
    v_membership_status := 'joined';
  end if;

  return jsonb_build_object(
    'success', true,
    'data', jsonb_build_object(
      'company_id', v_company.id,
      'company_name', v_company.name,
      'membership_status', v_membership_status
    )
  );
end;
$$

create or replace function public.generate_invite_code()
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  chars text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  result text;
  attempts integer := 0;
begin
  loop
    result := '';

    for i in 1..8 loop
      result := result || substr(chars, 1 + floor(random() * length(chars))::integer, 1);
    end loop;

    exit when not exists (
      select 1
      from public.companies
      where companies.invite_code = result
    );

    attempts := attempts + 1;

    if attempts > 10 then
      raise exception 'Could not generate unique invite code';
    end if;
  end loop;

  return result;
end;
$$

do $$
begin
  if not exists (
    select 1
    from pg_constraint
    where conname = 'profiles_email_key'
      and conrelid = 'public.profiles'::regclass
  ) then
    alter table public.profiles
      add constraint profiles_email_key unique (email);
  end if;

  if not exists (
    select 1
    from pg_constraint
    where conname = 'profiles_username_key'
      and conrelid = 'public.profiles'::regclass
  ) then
    alter table public.profiles
      add constraint profiles_username_key unique (username);
  end if;

  if not exists (
    select 1
    from pg_constraint
    where conname = 'profiles_username_length'
      and conrelid = 'public.profiles'::regclass
  ) then
    alter table public.profiles
      add constraint profiles_username_length check (char_length(username) between 2 and 20);
  end if;
end;
$$

do $$
begin
  if not exists (
    select 1
    from pg_constraint
    where conname = 'companies_name_key'
      and conrelid = 'public.companies'::regclass
  ) then
    alter table public.companies
      add constraint companies_name_key unique (name);
  end if;
end;
$$

do $$
begin
  if exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'company_members'
      and column_name = 'created_at'
  ) and not exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'company_members'
      and column_name = 'joined_at'
  ) then
    alter table public.company_members rename column created_at to joined_at;
  end if;

  if not exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'company_members'
      and column_name = 'joined_at'
  ) then
    alter table public.company_members
      add column joined_at timestamp with time zone not null default now();
  end if;
end;
$$

create or replace function public.create_or_update_profile(username text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid;
  v_username text;
  v_email text;
  v_profile public.profiles%rowtype;
  v_constraint text;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    return jsonb_build_object(
      'success', false,
      'error_code', 'NOT_AUTHENTICATED',
      'message', 'Utilisateur non connecté.'
    );
  end if;

  v_username := nullif(btrim($1), '');

  if v_username is null then
    return jsonb_build_object(
      'success', false,
      'error_code', 'USERNAME_REQUIRED',
      'message', 'Le pseudo est obligatoire.'
    );
  end if;

  if char_length(v_username) < 2 or char_length(v_username) > 20 then
    return jsonb_build_object(
      'success', false,
      'error_code', 'USERNAME_INVALID',
      'message', 'Le pseudo doit contenir entre 2 et 20 caractères.'
    );
  end if;

  v_email := coalesce(auth.jwt() ->> 'email', v_user_id::text || '@missing.local');

  insert into public.profiles (id, email, username)
  values (v_user_id, v_email, v_username)
  on conflict (id) do update
    set email = coalesce(excluded.email, public.profiles.email),
        username = excluded.username
  returning *
  into v_profile;

  return jsonb_build_object(
    'success', true,
    'data', jsonb_build_object(
      'id', v_profile.id,
      'email', v_profile.email,
      'username', v_profile.username,
      'avatar_url', v_profile.avatar_url,
      'created_at', v_profile.created_at,
      'updated_at', v_profile.updated_at
    )
  );
exception
  when unique_violation then
    get stacked diagnostics v_constraint = constraint_name;

    if v_constraint in ('profiles_username_key', 'profiles_username_unique') then
      return jsonb_build_object(
        'success', false,
        'error_code', 'USERNAME_TAKEN',
        'message', 'Ce pseudo est déjà utilisé.'
      );
    end if;

    raise;
end;
$$

