create or replace function public.upsert_prediction(
  p_match_id uuid,
  p_home_score integer,
  p_away_score integer,
  p_is_boosted boolean default false
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid;
  v_kickoff_at timestamptz;
  v_prediction public.predictions%rowtype;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    return jsonb_build_object(
      'success', false,
      'error_code', 'NOT_AUTHENTICATED',
      'message', 'Utilisateur non connecté.'
    );
  end if;

  if p_home_score is null
     or p_away_score is null
     or p_home_score < 0
     or p_home_score > 99
     or p_away_score < 0
     or p_away_score > 99 then
    return jsonb_build_object(
      'success', false,
      'error_code', 'INVALID_SCORE',
      'message', 'Les scores doivent être des entiers entre 0 et 99.'
    );
  end if;

  select m.kickoff_at
  into v_kickoff_at
  from public.matches m
  where m.id = p_match_id;

  if v_kickoff_at is null then
    return jsonb_build_object(
      'success', false,
      'error_code', 'MATCH_NOT_FOUND',
      'message', 'Match introuvable.'
    );
  end if;

  if now() >= v_kickoff_at - interval '15 minutes' then
    return jsonb_build_object(
      'success', false,
      'error_code', 'MATCH_LOCKED',
      'message', 'Le match est verrouillé.'
    );
  end if;

  if coalesce(p_is_boosted, false) and exists (
    select 1
    from public.predictions p
    where p.user_id = v_user_id
      and p.is_boosted = true
      and p.match_id <> p_match_id
  ) then
    return jsonb_build_object(
      'success', false,
      'error_code', 'BOOST_ALREADY_USED',
      'message', 'Le boost est déjà utilisé sur un autre match.'
    );
  end if;

  insert into public.predictions (
    user_id,
    match_id,
    home_score,
    away_score,
    is_boosted
  )
  values (
    v_user_id,
    p_match_id,
    p_home_score,
    p_away_score,
    coalesce(p_is_boosted, false)
  )
  on conflict (user_id, match_id) do update
    set home_score = excluded.home_score,
        away_score = excluded.away_score,
        is_boosted = excluded.is_boosted
  returning *
  into v_prediction;

  return jsonb_build_object(
    'success', true,
    'data', jsonb_build_object(
      'prediction_id', v_prediction.id,
      'match_id', v_prediction.match_id,
      'home_score', v_prediction.home_score,
      'away_score', v_prediction.away_score,
      'is_boosted', v_prediction.is_boosted,
      'updated_at', v_prediction.updated_at
    )
  );
exception
  when unique_violation then
    return jsonb_build_object(
      'success', false,
      'error_code', 'BOOST_ALREADY_USED',
      'message', 'Le boost est déjà utilisé sur un autre match.'
    );
end;
$$

do $$
begin
  if (select count(*) from public.matches where stage = 'group' and fifa_match_number is not null) <> 72 then
    raise exception 'Official match reseed expected 72 group matches with fifa_match_number.';
  end if;
end;
$$

create or replace function public.set_favorite_team(p_team_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid;
  v_team_name text;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    return jsonb_build_object('success', false, 'error_code', 'NOT_AUTHENTICATED', 'message', 'Utilisateur non connecté.');
  end if;

  if p_team_id is not null then
    select name into v_team_name from public.teams where id = p_team_id;
    if v_team_name is null then
      return jsonb_build_object('success', false, 'error_code', 'TEAM_NOT_FOUND', 'message', 'Équipe introuvable.');
    end if;
  end if;

  update public.profiles
  set favorite_team_id = p_team_id
  where id = v_user_id;

  return jsonb_build_object('success', true, 'data', jsonb_build_object('team_id', p_team_id, 'team_name', v_team_name));
end;
$$

create or replace function public.delete_my_account()
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null then
    raise exception 'NOT_AUTHENTICATED';
  end if;
  delete from auth.users where id = auth.uid();
end;
$$
